fn is_digit(c: Str) -> Bool {
  return c == "0" or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn parse_item(piece: Str) -> Option[Pair[Str, Int]] {
  let fields = piece.split(":")
  if fields.len() != 2 {
    return None
  }
  let name = fields.get_or(0, "")
  let qty_text = fields.get_or(1, "")
  if name.is_empty() or qty_text.is_empty() {
    return None
  }
  if not (qty_text.chars().all(fn(c) => is_digit(c))) {
    return None
  }
  let qty = qty_text.to_int().unwrap_or(0)
  if qty <= 0 {
    return None
  }
  return Some(Pair { first: name, second: qty })
}

fn parse_order(order: Str) -> Result[List[Pair[Str, Int]], Str] {
  let parts = order.split(" ")
  let id = parts.get_or(0, "")
  if parts.len() != 2 or id.is_empty() {
    return Err("bad order {id}")
  }
  var out: List[Pair[Str, Int]] = []
  for piece in parts.get_or(1, "").split(",") {
    match parse_item(piece) {
      Some(p) => { out = out.push(p) },
      None => { return Err("bad order {id}") },
    }
  }
  return Ok(out)
}

fn known(stock: Map[Str, Int], wanted: List[Pair[Str, Int]]) -> Bool {
  return wanted.all(fn(p) => stock.has(p.first))
}

fn consume(stock: Map[Str, Int], wanted: List[Pair[Str, Int]]) -> Map[Str, Int] {
  return wanted.fold(stock, fn(acc, p) => acc.set(p.first, acc.get(p.first).unwrap_or(0) - p.second))
}

fn enough(after: Map[Str, Int], wanted: List[Pair[Str, Int]]) -> Bool {
  return wanted.all(fn(p) => after.get(p.first).unwrap_or(0) >= 0)
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  var have: Map[Str, Int] = stock
  var filled: List[Str] = []
  for order in orders {
    let wanted = parse_order(order)?
    let id = order.split(" ").get_or(0, "")
    if not (known(have, wanted)) {
      return Err("bad order {id}")
    }
    let after = consume(have, wanted)
    if enough(after, wanted) {
      have = after
      filled = filled.push(id)
    }
  }
  return Ok(filled)
}
